package com.way2jobs.scraper.source;
import com.way2jobs.scraper.config.ScraperProperties; import com.way2jobs.scraper.model.ScrapedJob; import lombok.extern.slf4j.Slf4j; import org.jsoup.Jsoup; import org.jsoup.nodes.*; import org.springframework.stereotype.Component; import java.util.*; import java.util.regex.*;
@Component @Slf4j public class FreeJobAlertSource implements JobSource { private static final Pattern VACANCIES=Pattern.compile("(\\d{1,6})\\s*(?:posts?|vacanc(?:y|ies))",Pattern.CASE_INSENSITIVE); public String name(){return "FreeJobAlert";} public List<ScrapedJob> fetch(String state,String url,ScraperProperties p)throws Exception { Document d=Jsoup.connect(url).userAgent(p.getUserAgent()).timeout(p.getTimeoutMs()).get(); List<ScrapedJob> out=new ArrayList<>(); boolean found=false; for(Element table:d.select("table")){Element header=table.selectFirst("tr:has(th)"); if(header==null)continue; Map<String,Integer> cols=columns(header); if(!cols.containsKey("title"))continue; found=true; for(Element row:table.select("tr")){if(row.selectFirst("th")!=null)continue; try{List<Element> cells=row.select("> td"); if(!cells.isEmpty()){ScrapedJob j=row(cells,cols,state,url); if(j!=null)out.add(j);}}catch(Exception e){log.warn("Unable to parse FreeJobAlert row from {}",url,e);}}} if(!found)log.warn("No recognised result table found at {}",url); return out;} private Map<String,Integer> columns(Element h){Map<String,Integer> m=new HashMap<>(); List<Element> hs=h.select("> th, > td"); for(int i=0;i<hs.size();i++){String t=hs.get(i).text().toLowerCase(Locale.ROOT); if((t.contains("title")||t.contains("post"))&&!m.containsKey("title"))m.put("title",i); if((t.contains("qualification")||t.contains("eligibility"))&&!m.containsKey("qualification"))m.put("qualification",i); if((t.contains("last date")||t.contains("last dt")||t.contains("closing"))&&!m.containsKey("lastDate"))m.put("lastDate",i); if((t.contains("apply")||t.contains("notification")||t.contains("details")||t.contains("more info"))&&!m.containsKey("link"))m.put("link",i); if((t.contains("vacancy")||t.contains("vacancies"))&&!m.containsKey("vacancies"))m.put("vacancies",i);}return m;} private ScrapedJob row(List<Element> c,Map<String,Integer> m,String state,String source){Element title=cell(c,m.get("title"));if(title==null)return null; ScrapedJob j=new ScrapedJob();j.setTitle(title.text());j.setOrganizationName(title.text());j.setQualification(text(cell(c,m.get("qualification"))));j.setLastDateRaw(text(cell(c,m.get("lastDate"))));j.setVacanciesRaw(text(cell(c,m.get("vacancies"))));if(j.getVacanciesRaw()==null){Matcher x=VACANCIES.matcher(j.getTitle());if(x.find())j.setVacanciesRaw(x.group(1));}Element link=Optional.ofNullable(cell(c,m.get("link"))).map(e->e.selectFirst("a[href]")).orElse(null);if(link==null)link=c.stream().map(e->e.selectFirst("a[href]")).filter(Objects::nonNull).findFirst().orElse(null);if(link!=null){j.setNotificationUrl(link.absUrl("href"));j.setApplyUrl(link.absUrl("href"));}j.setSourceStateName(state);j.setSourceUrl(source);return j;} private Element cell(List<Element> c,Integer i){return i!=null&&i>=0&&i<c.size()?c.get(i):null;} private String text(Element e){return e==null?null:e.text();}}
